function generateMinorArcana() {
  const cards = [];
  let id = 22;
  for (const suit of suitConfig) {
    const suitMeanings = minorMeanings[suit.nameEn];
    for (let num = 1; num <= 10; num++) {
      const meaningKey = num === 1 ? "Ace" : String(num);
      const m = suitMeanings[meaningKey];
      const padded = String(num).padStart(2, "0");
      const roman = romanNumerals[num];
      const numberWord = numberWordLabels[num];
      cards.push({
        id: id++,
        name: `${suit.name} ${roman}`,
        nameEn: `${numberWord} of ${suit.nameEn}`,
        arcana: "minor",
        suit: suit.name,
        image: `${IMG_BASE}/${suit.prefix}${padded}.jpg`,
        visualDescription: m.visual,
        upright: m.upright,
        reversed: m.reversed,
        uprightDeep: m.uprightDeep,
        reversedWarning: m.reversedWarning,
        description: `${suit.name} ${roman} \u5C5E\u4E8E${suit.element}\u5143\u7D20\uFF0C\u4EE3\u8868${m.upright.split("\u3001")[0]}\u7684\u80FD\u91CF\u3002`
      });
    }
    for (const court of courtCards) {
      const m = suitMeanings[court.en];
      const padded = String(court.num).padStart(2, "0");
      cards.push({
        id: id++,
        name: `${suit.name}${court.cn}`,
        nameEn: `${court.en} of ${suit.nameEn}`,
        arcana: "minor",
        suit: suit.name,
        image: `${IMG_BASE}/${suit.prefix}${padded}.jpg`,
        visualDescription: m.visual,
        upright: m.upright,
        reversed: m.reversed,
        uprightDeep: m.uprightDeep,
        reversedWarning: m.reversedWarning,
        description: `${suit.name}${court.cn}\u4EE3\u8868${suit.element}\u5143\u7D20\u4E2D${m.upright.split("\u3001")[0]}\u7684\u4EBA\u683C\u7279\u8D28\u3002`
      });
    }
  }
  return cards;
}
var allTarotCards = [...majorArcana, ...generateMinorArcana()];
var getRandomCards = (count) => {
  const shuffled = [...allTarotCards].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
};

// src/lib/mcp/tools/list-tarot-cards.ts
var list_tarot_cards_default = defineTool({
  name: "list_tarot_cards",
  title: "List tarot cards",
  description: "List the tarot deck used by this app (78 cards). Optionally filter to major or minor arcana. Returns names and short upright/reversed keywords.",
  inputSchema: {
    arcana: z.enum(["all", "major", "minor"]).optional().describe("Which arcana to list. Defaults to all.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ arcana = "all" }) => {
    const cards = allTarotCards.filter(
      (c) => arcana === "all" || c.arcana === arcana
    );
    const rows = cards.map((c) => ({
      id: c.id,
      name: c.name,
      nameEn: c.nameEn,
      arcana: c.arcana,
      suit: c.suit,
      number: c.number,
      upright: c.upright,
      reversed: c.reversed
    }));
    return {
      content: [
        {
          type: "text",
          text: rows.map(
            (r) => `${r.name} (${r.nameEn}) \u2014 \u6B63\u4F4D: ${r.upright} / \u9006\u4F4D: ${r.reversed}`
          ).join("\n")
        }
      ],
      structuredContent: { count: rows.length, cards: rows }
    };
  }
});

// src/lib/mcp/tools/get-tarot-card.ts
import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z2 } from "npm:zod@^3.25.76";
var get_tarot_card_default = defineTool2({
  name: "get_tarot_card",
  title: "Get tarot card meaning",
  description: "Look up one tarot card by Chinese or English name (or partial name) and return its full meaning: imagery, upright and reversed interpretations, and background.",
  inputSchema: {
    name: z2.string().min(1).describe("Card name in Chinese or English, e.g. \u611A\u8005 or The Fool.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ name }) => {
    const q = name.trim().toLowerCase();
    const card = allTarotCards.find(
      (c) => c.name === name.trim() || c.nameEn.toLowerCase() === q
    ) ?? allTarotCards.find(
      (c) => c.name.includes(name.trim()) || c.nameEn.toLowerCase().includes(q)
    );
    if (!card) {
      throw new ToolError(`No tarot card matched "${name}".`);
    }
    const text = [
      `${card.name}\uFF08${card.nameEn}\uFF09${card.number ? `\xB7 ${card.number}` : ""}`,
      `\u724C\u7EC4\uFF1A${card.arcana === "major" ? "\u5927\u963F\u5C14\u5361\u7EB3" : `\u5C0F\u963F\u5C14\u5361\u7EB3${card.suit ? ` \xB7 ${card.suit}` : ""}`}`,
      `\u753B\u9762\uFF1A${card.visualDescription}`,
      `\u6B63\u4F4D\u5173\u952E\u8BCD\uFF1A${card.upright}`,
      `\u6B63\u4F4D\u89E3\u8BFB\uFF1A${card.uprightDeep}`,
      `\u9006\u4F4D\u5173\u952E\u8BCD\uFF1A${card.reversed}`,
      `\u9006\u4F4D\u63D0\u9192\uFF1A${card.reversedWarning}`,
      `\u80CC\u666F\uFF1A${card.description}`
    ].join("\n");
    return { content: [{ type: "text", text }], structuredContent: { card } };
  }
});

// src/lib/mcp/tools/draw-tarot-spread.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^3.25.76";
var SPREADS = {
  timeline: { label: "\u65F6\u95F4\u6D41\u724C\u9635\uFF08\u8FC7\u53BB\xB7\u73B0\u5728\xB7\u672A\u6765\uFF09", positions: ["\u8FC7\u53BB", "\u73B0\u5728", "\u672A\u6765"] },
  choice: { label: "\u4E8C\u9009\u4E00\u724C\u9635", positions: ["\u9009\u9879A", "\u9009\u9879B"] },
  single: { label: "\u5355\u5F20\u6307\u5F15", positions: ["\u6307\u5F15"] }
};
var draw_tarot_spread_default = defineTool3({
  name: "draw_tarot_spread",
  title: "Draw a tarot spread",
  description: "Shuffle this app's tarot deck and draw a spread (timeline, choice, or single card) with random upright/reversed orientation. Returns each drawn card with its position and meanings so the caller can interpret the reading.",
  inputSchema: {
    question: z3.string().optional().describe("The querent's question, echoed back in the result."),
    spread: z3.enum(["timeline", "choice", "single"]).optional().describe("Spread type. Defaults to timeline (past / present / future).")
  },
  annotations: { readOnlyHint: true, idempotentHint: false, openWorldHint: false },
  handler: ({ question, spread = "timeline" }) => {
    const config = SPREADS[spread];
    const cards = getRandomCards(config.positions.length);
    const drawn = cards.map((card, i) => {
      const isReversed = Math.random() < 0.5;
      return {
        position: config.positions[i],
        name: card.name,
        nameEn: card.nameEn,
        orientation: isReversed ? "\u9006\u4F4D" : "\u6B63\u4F4D",
        keywords: isReversed ? card.reversed : card.upright,
        meaning: isReversed ? card.reversedWarning : card.uprightDeep,
        description: card.description
      };
    });
    const text = [
      question ? `\u95EE\u9898\uFF1A${question}` : null,
      `\u724C\u9635\uFF1A${config.label}`,
      ...drawn.map(
        (d) => `\u4F4D\u7F6E\u300C${d.position}\u300D\uFF1A${d.name}\uFF08${d.nameEn}\uFF09\u2014 ${d.orientation}
\u5173\u952E\u8BCD\uFF1A${d.keywords}
\u89E3\u8BFB\uFF1A${d.meaning}`
      )
    ].filter(Boolean).join("\n\n");
    return {
      content: [{ type: "text", text }],
      structuredContent: { spread, question: question ?? null, cards: drawn }
    };
  }
});

